checks.script:
set -e
cd /app
python3 - <<'PY'
from PIL import Image
from pathlib import Path
im=Image.open('chess_board.png').convert('RGB')
assert im.size==(640,640)
# Pure foreground counts identify this image's sprite classes.  Coordinate-label
# artifacts are below 100 pixels and cannot be mistaken for a chessman.
black={777:'p',823:'p',718:'r',542:'b',512:'q',463:'k'}
white={261:'P',265:'P',266:'P',292:'R',294:'R',161:'B',207:'K',263:'Q'}
B={}; inventory=[]
for row in range(8):
 for col in range(8):
  q=im.crop((80*col,80*row,80*(col+1),80*(row+1)))
  px=list(q.getdata()); nb=px.count((0,0,0)); nw=px.count((255,255,255))
  if max(nb,nw)<100: continue
  if nb:
   assert nb in black, (col,row,nb)
   p=black[nb]
  else:
   assert nw in white, (col,row,nw)
   p=white[nw]
  B[col,8-row]=p
  inventory.append(chr(97+col)+str(8-row)+p)
expected=['a8r','c8b','d8q','f8r','b7p','f7p','g7p','a6p','c6p','e6p','d5p','e5P','f5k','g5b','h5P','a3P','c3P','b2P','e2Q','f2P','g2P','a1R','c1B','e1K','h1R']
assert inventory==expected, inventory
N=((1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1))
R=((1,0),(-1,0),(0,1),(0,-1)); D=((1,1),(1,-1),(-1,1),(-1,-1))
def side(p): return p.isupper() if p else None
def attack(b,s,w):
 x,y=s
 for dx in (-1,1):
  if b.get((x-dx,y-(1 if w else -1)))==('P' if w else 'p'): return True
 for dx,dy in N:
  if b.get((x+dx,y+dy))==('N' if w else 'n'): return True
 for dx in (-1,0,1):
  for dy in (-1,0,1):
   if (dx or dy) and b.get((x+dx,y+dy))==('K' if w else 'k'): return True
 for dirs,pcs in ((R,'RQ' if w else 'rq'),(D,'BQ' if w else 'bq')):
  for dx,dy in dirs:
   a,c=x+dx,y+dy
   while 0<=a<8 and 1<=c<=8:
    p=b.get((a,c))
    if p:
     if p in pcs: return True
     break
    a+=dx; c+=dy
 return False
def pseudo(b,w):
 for (x,y),p in list(b.items()):
  if side(p)!=w: continue
  t=p.lower()
  if t=='p':
   dy=1 if w else -1; ny=y+dy; start=2 if w else 7
   if 1<=ny<=8 and (x,ny) not in b:
    yield (x,y),(x,ny)
    if y==start and (x,y+2*dy) not in b: yield (x,y),(x,y+2*dy)
   for dx in (-1,1):
    q=b.get((x+dx,ny))
    if 0<=x+dx<8 and q and side(q)!=w: yield (x,y),(x+dx,ny)
   continue
  if t=='n': dirs=N; limit=1
  elif t=='k': dirs=R+D; limit=1
  elif t=='r': dirs=R; limit=8
  elif t=='b': dirs=D; limit=8
  else: dirs=R+D; limit=8
  for dx,dy in dirs:
   a,c=x+dx,y+dy; steps=0
   while 0<=a<8 and 1<=c<=8 and side(b.get((a,c)))!=w and steps<limit:
    yield (x,y),(a,c)
    if (a,c) in b: break
    a+=dx; c+=dy; steps+=1
def apply(b,m):
 c=b.copy(); c[m[1]]=c.pop(m[0]); return c
def legal(b,w):
 out=[]
 for m in pseudo(b,w):
  c=apply(b,m); king=next(s for s,p in c.items() if p==('K' if w else 'k'))
  if not attack(c,king,not w): out.append(m)
 return out
def name(m): return chr(97+m[0][0])+str(m[0][1])+chr(97+m[1][0])+str(m[1][1])
assert not attack(B,next(s for s,p in B.items() if p=='k'),True)
mates=[]
for m in legal(B,True):
 c=apply(B,m); bk=next(s for s,p in c.items() if p=='k')
 if attack(c,bk,True) and not legal(c,False): mates.append(name(m))
assert mates==['g2g4'], mates
assert Path('move.txt').read_text().splitlines()==mates
PY

