import csv, datetime as dt, json
import pyarrow.parquet as pq

def norm(r):
    status = r.get('status')
    if status in (None, ''):
        for key in ('is_active', 'active'):
            if key in r and r[key] is not None:
                status = 'active' if bool(r[key]) else 'inactive'
                break
    d = r.get('registration_date', r.get('created_at', r.get('joined')))
    return {'user_id': int(r.get('user_id', r.get('id', r.get('userId')))),
            'name': r.get('full_name', r.get('name', r.get('userName'))),
            'email': r.get('email', r.get('email_address')),
            'created_date': None if d in (None, '') else dt.date.fromisoformat(str(d)[:10]).isoformat(),
            'status': status}
with open('/data/source_a/users.json', encoding='utf-8') as f: raw = {'source_a': json.load(f)}
with open('/data/source_b/users.csv', encoding='utf-8', newline='') as f: raw['source_b'] = list(csv.DictReader(f))
raw['source_c'] = pq.read_table('/data/source_c/users.parquet').to_pylist()
sources = {source: {norm(r)['user_id']: norm(r) for r in rows} for source, rows in raw.items()}
expected = []
for uid in sorted(set().union(*(set(rows) for rows in sources.values()))):
    present = [s for s in ('source_a', 'source_b', 'source_c') if uid in sources[s]]
    for field in ('name', 'email', 'created_date', 'status'):
        values = {s: sources[s][uid][field] for s in present}
        if len(present) > 1 and len(set(values.values())) > 1:
            selected = next(sources[s][uid][field] for s in ('source_a', 'source_b', 'source_c') if uid in sources[s])
            expected.append({'user_id': uid, 'field': field, 'values': values, 'selected': selected})
with open('/app/conflicts.json', encoding='utf-8') as f: report = json.load(f)
assert set(report) == {'total_conflicts', 'conflicts'}
assert report['total_conflicts'] == len(report['conflicts']) == len(expected)
assert report['conflicts'] == expected
