work=$(mktemp -d /tmp/check-c4.XXXXXX)
trap 'rm -rf "$work"' EXIT
python - /app/c4_sample "$work/original.json" <<'PY'
import hashlib,json,os,stat,sys
def inv(root):
 out=[]
 for base,ds,fs in os.walk(root,followlinks=False):
  ds.sort(); fs.sort()
  for n in ds+fs:
   p=os.path.join(base,n); s=os.lstat(p); r=os.path.relpath(p,root)
   if stat.S_ISREG(s.st_mode):
    h=hashlib.sha256()
    with open(p,'rb') as f:
     for b in iter(lambda:f.read(1048576),b''): h.update(b)
    out.append([r,'file',s.st_size,h.hexdigest()])
   elif stat.S_ISDIR(s.st_mode): out.append([r,'dir',0,''])
   elif stat.S_ISLNK(s.st_mode): out.append([r,'symlink',0,os.readlink(p)])
   else: raise SystemExit('unsupported type')
 return out
json.dump(inv(sys.argv[1]),open(sys.argv[2],'w'))
PY
PYTHONDONTWRITEBYTECODE=1 /app/.venv/bin/python -B /app/compress.py /app/c4_sample "$work/resharded"
python - "$work/resharded" <<'PY'
import os,sys
for base,ds,fs in os.walk(sys.argv[1]):
 if len(ds)+len(fs)>30: raise SystemExit('directory entry limit exceeded')
 for n in fs:
  if os.lstat(os.path.join(base,n)).st_size>15000000: raise SystemExit('file size limit exceeded')
PY
PYTHONDONTWRITEBYTECODE=1 /app/.venv/bin/python -B /app/decompress.py "$work/resharded"
python - "$work/resharded" "$work/original.json" <<'PY'
import hashlib,json,os,stat,sys
def inv(root):
 out=[]
 for base,ds,fs in os.walk(root,followlinks=False):
  ds.sort(); fs.sort()
  for n in ds+fs:
   p=os.path.join(base,n); s=os.lstat(p); r=os.path.relpath(p,root)
   if stat.S_ISREG(s.st_mode):
    h=hashlib.sha256()
    with open(p,'rb') as f:
     for b in iter(lambda:f.read(1048576),b''): h.update(b)
    out.append([r,'file',s.st_size,h.hexdigest()])
   elif stat.S_ISDIR(s.st_mode): out.append([r,'dir',0,''])
   elif stat.S_ISLNK(s.st_mode): out.append([r,'symlink',0,os.readlink(p)])
   else: raise SystemExit('unsupported type')
 return out
if inv(sys.argv[1])!=json.load(open(sys.argv[2])): raise SystemExit('c4 restoration mismatch')
PY
